'use strict';

// MODULES //

var isArray = require( '@stdlib/assert/is-array' );
var isObject = require( '@stdlib/assert/is-object' );
var objectKeys = require( '@stdlib/utils/keys' );


// FUNCTIONS //

/**
* Returns a deep copy whose object keys are recursively sorted.
*
* @private
* @param {*} value - value
* @returns {*} canonical value
*
* @example
* var obj = {
*     'b': 2,
*     'a': 1
* };
*
* var out = canonical( obj );
* // returns { 'a': 1, 'b': 2 }
*
* @example
* var obj = {
*     'b': 2,
*     'a': 1
* };
*
* var out = canonical( [ obj ] );
* // returns [ { 'a': 1, 'b': 2 } ]
*/
function canonical( value ) {
	var keys;
	var out;
	var k;
	var i;

	if ( isArray( value ) ) {
		out = [];
		for ( i = 0; i < value.length; i++ ) {
			out.push( canonical( value[ i ] ) );
		}
		return out;
	}
	if ( isObject( value ) ) {
		keys = objectKeys( value ).sort();
		out = {};
		for ( i = 0; i < keys.length; i++ ) {
			k = keys[ i ];
			out[ k ] = canonical( value[ k ] );
		}
		return out;
	}
	return value;
}


// EXPORTS //

module.exports = canonical;
